const fs = require('fs')

module.exports = sync_rules
module.exports.is_allowed = is_allowed

// only these dirs are synced
const allowed_dirs = [
  '/org/gnome/shell/extensions/',
  '/org/gnome/desktop/wm/keybindings/',
  '/org/gnome/settings-daemon/plugins/media-keys/',
  '/org/gnome/desktop/interface/',
  '/org/gnome/desktop/background/' // the image itself is synced by wallpaper-sync, its file:// path is denied below
]
// keys owned by sources (extensions, wallpaper, themes), their values are names and hashes
const source_dirs = ['/extensions/', '/wallpaper/', '/themes/']
// per machine or private keys, never synced
const denied = [
  /monitor/i, // monitor ids, connectors and sizes
  /scaling-factor$/, // depends on the screen
  /history$/, // recent colors, played songs, ...
  /bguri$/, // file paths to images
  /^\/org\/gnome\/shell\/extensions\/space-bar\/state\// // runtime state
]

// rules plus this device's own excludes, saved in a local file and never synced
function sync_rules ({ file }) {
  const state = { exclude: [] }
  const api = { allowed_dirs, load, is_synced, exclude, include, list_excludes }
  return api

  async function load () { state.exclude = (await read_json(file))?.exclude || [] }
  function is_synced (key, value) { return is_allowed({ key, value, exclude: state.exclude }) }
  function list_excludes () { return state.exclude.slice() }
  async function exclude (path) {
    if (!state.exclude.includes(path)) state.exclude.push(path)
    await save()
  }
  async function include (path) {
    state.exclude = state.exclude.filter(p => p !== path)
    await save()
  }
  function save () { return fs.promises.writeFile(file, JSON.stringify({ exclude: state.exclude }, null, 2)) }
}

/***************************************
IS ALLOWED
an exclude is a key or a dir ending with /, like /extensions/<uuid>, /wallpaper/ or /themes/icons/<name>
***************************************/
function is_allowed ({ key, value = null, exclude = [] }) {
  const is_source = source_dirs.some(dir => key.startsWith(dir))
  if (!is_source && !allowed_dirs.some(dir => key.startsWith(dir))) return false
  if (is_source && value === null) return false // missing here, never sent as removed
  if (denied.some(pattern => pattern.test(key))) return false
  if (value && /file:\/\/|\/home\//.test(value)) return false // a path on this machine
  if (value && /([0-9a-f]{2}:){5}[0-9a-f]{2}/i.test(value)) return false // hardware addresses, like paired bluetooth devices
  return !exclude.some(path => path.endsWith('/') ? key.startsWith(path) : key === path)
}

function read_json (file) { return fs.promises.readFile(file, 'utf8').then(JSON.parse).catch(() => null) }
